import express, { type Request, Response, NextFunction } from "express";
import session from "express-session";
import connectPgSimple from "connect-pg-simple";
import MemoryStore from "memorystore";
import path from "path";
import { registerRoutes } from "./routes";
import { setupVite, serveStatic, log } from "./vite";
import { migratePlaintextPinToHashed } from "./services/migrationService";

const app = express();

// Trust proxy for production environments (required for secure cookies behind proxies)
if (process.env.NODE_ENV === 'production') {
  app.set('trust proxy', 1);
}

app.use(express.json());
app.use(express.urlencoded({ extended: false }));

// Validate session secret in production
if (process.env.NODE_ENV === 'production' && !process.env.SESSION_SECRET) {
  throw new Error('SESSION_SECRET environment variable is required in production');
}

// Configure session store - use MemoryStore for dev, PostgreSQL only if DATABASE_URL exists
let sessionStore;
if (process.env.DATABASE_URL) {
  const PgSession = connectPgSimple(session);
  sessionStore = new PgSession({
    conString: process.env.DATABASE_URL,
    tableName: 'session',
    createTableIfMissing: true
  });
  log('Using PostgreSQL session store');
} else {
  const MemStoreSession = MemoryStore(session);
  sessionStore = new MemStoreSession({
    checkPeriod: 86400000 // prune expired entries every 24h
  });
  log('Using MemoryStore session store');
}

// Session middleware configuration with security improvements
app.use(session({
  store: sessionStore,
  secret: process.env.SESSION_SECRET || (process.env.NODE_ENV === 'production' ? 
    (() => { throw new Error('SESSION_SECRET required in production') })() :
    'dev-session-secret-change-in-production'
  ),
  resave: false,
  saveUninitialized: false,
  rolling: true,
  cookie: {
    secure: process.env.NODE_ENV === 'production',
    httpOnly: true,
    sameSite: 'lax', // Prevent CSRF attacks
    maxAge: 24 * 60 * 60 * 1000 // 24 hours
  }
}));

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      if (logLine.length > 80) {
        logLine = logLine.slice(0, 79) + "…";
      }

      log(logLine);
    }
  });

  next();
});

// Serve content directory as static files with proper MIME types
app.use('/content', express.static(path.join(process.cwd(), 'content'), {
  setHeaders: (res, filePath) => {
    if (filePath.endsWith('.yaml') || filePath.endsWith('.yml')) {
      res.setHeader('Content-Type', 'text/yaml');
    } else if (filePath.endsWith('.md')) {
      res.setHeader('Content-Type', 'text/markdown');
    } else if (filePath.endsWith('.mdx')) {
      res.setHeader('Content-Type', 'text/markdown');
    }
  }
}));

(async () => {
  // Run PIN security migration before starting routes
  try {
    await migratePlaintextPinToHashed();
  } catch (error) {
    console.error('Critical: PIN migration failed', error);
    process.exit(1);
  }

  const server = await registerRoutes(app);

  app.use((err: any, _req: Request, res: Response, _next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    res.status(status).json({ message });
    console.error(err);
    return;
  });

  // importantly only setup vite in development and after
  // setting up all the other routes so the catch-all route
  // doesn't interfere with the other routes
  if (app.get("env") === "development") {
    await setupVite(app, server);
  } else {
    serveStatic(app);
  }

  // ALWAYS serve the app on the port specified in the environment variable PORT
  // Other ports are firewalled. Default to 5000 if not specified.
  // this serves both the API and the client.
  // It is the only port that is not firewalled.
  const port = parseInt(process.env.PORT || '5000', 10);
  server.listen({
    port,
    host: "0.0.0.0",
    reusePort: true,
  }, () => {
    log(`serving on port ${port}`);
  });
})();

