  }

  /* Smooth scrolling */
  html {
    scroll-behavior: smooth;
  }

  /* Respect reduced motion preference */
  @media (prefers-reduced-motion: reduce) {
    html {
      scroll-behavior: auto;
    }

    *,
    *::before,
    *::after {
      animation-duration: 0.01ms !important;
      animation-iteration-count: 1 !important;
      transition-duration: 0.01ms !important;
      scroll-behavior: auto !important;
    }
  }

  /* Custom scrollbar for webkit browsers */
  ::-webkit-scrollbar {
    width: 8px;
  }

  ::-webkit-scrollbar-track {
    @apply bg-muted;
  }

  ::-webkit-scrollbar-thumb {
    @apply rounded-full;
    background-color: hsl(var(--muted-foreground) / 0.2);
  }

  ::-webkit-scrollbar-thumb:hover {
    background-color: hsl(var(--muted-foreground) / 0.3);
  }
}

@layer components {
  /* Custom styles for large tap targets on mobile */
  @media (max-width: 768px) {
    button {
      min-height: 44px;
      min-width: 44px;
    }

    input, select, textarea {
      min-height: 44px;
    }
  }

  /* Loading spinner animation */
  .fa-spin {
    animation: fa-spin 2s infinite linear;
  }

  @keyframes fa-spin {
    0% {
      transform: rotate(0deg);
    }
    100% {
      transform: rotate(360deg);
    }
  }

  /* Reduce spinner animation for reduced motion */
  @media (prefers-reduced-motion: reduce) {
    .fa-spin {
      animation: none;
    }
  }

  /* Photo upload area styles */
  .photo-upload-area {
    transition: all 0.2s ease-in-out;
  }

  .photo-upload-area:hover {
    border-color: hsl(var(--primary) / 0.5);
    background-color: hsl(var(--primary) / 0.05);
  }

  .photo-upload-area.drag-active {
    @apply border-primary scale-105;
    background-color: hsl(var(--primary) / 0.1);
  }

  /* Card hover effects */
  .card-hover {
    transition: all 0.2s ease-in-out;
  }

  .card-hover:hover {
    @apply shadow-md transform translate-y-[-2px];
  }

  /* Status badge animations */
  .status-badge {
    animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
  }

  @keyframes pulse {
    0%, 100% {
      opacity: 1;
    }
    50% {
      opacity: .8;
    }
  }

  /* Disable pulse animation for reduced motion */
  @media (prefers-reduced-motion: reduce) {
    .status-badge {
      animation: none;
    }
  }
}

@layer utilities {
  /* Mobile-first responsive utilities */
  .tap-target {
    @apply min-h-[44px] min-w-[44px];
  }

  /* Text truncation utilities */
  .truncate-2 {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  .truncate-3 {
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  /* Focus ring utilities */
  .focus-ring {
    @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2;
  }

  /* Safe area utilities for mobile devices */
  .safe-top {
    padding-top: env(safe-area-inset-top);
  }

  .safe-bottom {
    padding-bottom: env(safe-area-inset-bottom);
  }

  .safe-left {
    padding-left: env(safe-area-inset-left);
  }

  .safe-right {
    padding-right: env(safe-area-inset-right);
  }
}

/* Print styles for PDF generation */
@media print {
  body {
    @apply text-black bg-white;
  }

  .no-print {
    display: none !important;
  }

  .print-only {
    display: block !important;
  }

  /* Ensure colors print correctly */
  * {
    -webkit-print-color-adjust: exact !important;
    color-adjust: exact !important;
  }
}

