                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      <FormField
                        control={settingsForm.control}
                        name="sendgridApiKey"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>SendGrid API Key</FormLabel>
                            <FormControl>
                              <Input 
                                type="password" 
                                placeholder="SG.xxxxxxxxxxxxx" 
                                {...field} 
                                data-testid="input-sendgrid-api-key"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                      <FormField
                        control={settingsForm.control}
                        name="fromEmail"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel>From Email</FormLabel>
                            <FormControl>
                              <Input 
                                type="email" 
                                {...field} 
                                data-testid="input-from-email"
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />
                    </div>
                    <FormField
                      control={settingsForm.control}
                      name="siteUrl"
                      render={({ field }) => (
                        <FormItem className="mt-4">
                          <FormLabel>Site URL</FormLabel>
                          <FormControl>
                            <Input 
                              type="url" 
                              {...field} 
                              data-testid="input-site-url"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />

                    <Alert className="mt-4">
                      <AlertTriangle className="h-4 w-4" />
                      <AlertDescription>
                        <strong>Email Status:</strong> {settings?.sendgridApiKey ? 'Configured' : 'Not configured'}
                        {!settings?.sendgridApiKey && (
                          <span className="block mt-1 text-xs">
                            Quotes will be available for download and manual sharing until email is configured.
                          </span>
                        )}
                      </AlertDescription>
                    </Alert>
                  </div>

                  <div className="flex justify-end space-x-4 pt-6 border-t">
                    <Button 
                      type="button" 
                      variant="outline"
                      onClick={() => settingsForm.reset(settings)}
                      data-testid="button-reset-settings"
                    >
                      Reset
                    </Button>
                    <Button 
                      type="submit"
                      disabled={updateSettingsMutation.isPending}
                      data-testid="button-save-settings"
                    >
                      {updateSettingsMutation.isPending ? (
                        <>
                          <i className="fas fa-spinner fa-spin mr-2"></i>
                          Saving...
                        </>
                      ) : (
                        <>
                          <Save className="mr-2" size={16} />
                          Save Settings
                        </>
                      )}
                    </Button>
                  </div>
                </form>
              </Form>
            </CardContent>
          </Card>

          {/* Security Settings */}
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center">
                <Shield className="mr-2" size={20} />
                Security
              </CardTitle>
            </CardHeader>
            <CardContent>
              {!showPinChange ? (
                <div className="text-center py-6">
                  <p className="text-muted-foreground mb-4">
                    Change your owner PIN for dashboard access
                  </p>
                  <Button 
                    onClick={() => setShowPinChange(true)}
                    data-testid="button-change-pin"
                  >
                    Change PIN
                  </Button>
                </div>
              ) : (
                <Form {...pinForm}>
                  <form onSubmit={pinForm.handleSubmit(onPinSubmit)} className="max-w-md space-y-4">
                    <FormField
                      control={pinForm.control}
                      name="currentPin"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Current PIN</FormLabel>
                          <FormControl>
                            <Input 
                              type="password" 
                              placeholder="Enter current PIN" 
                              {...field} 
                              data-testid="input-current-pin"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={pinForm.control}
                      name="newPin"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>New PIN (4-6 digits)</FormLabel>
                          <FormControl>
                            <Input 
                              type="password" 
                              placeholder="Enter new PIN" 
                              {...field} 
                              data-testid="input-new-pin"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <FormField
                      control={pinForm.control}
                      name="confirmPin"
                      render={({ field }) => (
                        <FormItem>
                          <FormLabel>Confirm New PIN</FormLabel>
                          <FormControl>
                            <Input 
                              type="password" 
                              placeholder="Confirm new PIN" 
                              {...field} 
                              data-testid="input-confirm-pin"
                            />
                          </FormControl>
                          <FormMessage />
                        </FormItem>
                      )}
                    />
                    <div className="flex space-x-3">
                      <Button 
                        type="button" 
                        variant="outline"
                        onClick={() => {
                          setShowPinChange(false);
                          pinForm.reset();
                        }}
                        data-testid="button-cancel-pin-change"
