      {/* SEO */}
      <SeoHead 
        title="Case Studies - Real Results | HwinNwin"
        description="Real results from real businesses. See how HwinNwin has helped companies scale with AI automation, creative systems, and strategic consulting in Melbourne, Australia."
        ogTitle="Case Studies - Real Business Results | HwinNwin"
        ogDescription="Discover client success stories: From operations optimization to content automation. Real case studies with measurable results."
        canonicalUrl={`${SITE_CONFIG.baseUrl}/hwin/work`}
        keywords={['case studies', 'business results', 'client success', 'AI automation', 'Melbourne consulting', 'implementation', 'ROI']}
      />
      {/* Hero Section */}
      <section className="py-20 lg:py-32 bg-gradient-to-b from-background to-muted/20" data-testid="case-studies-hero">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto text-center space-y-8">
            <h1 className="text-4xl lg:text-6xl font-bold text-charcoal dark:text-hwin-white leading-tight" data-testid="case-studies-headline">
              Case Studies
            </h1>

            <p className="text-xl text-muted-foreground max-w-2xl mx-auto" data-testid="case-studies-subtitle">
              Real results from real businesses. See how we've helped companies scale with structure, mindset, and excellence.
            </p>
          </div>
        </div>
      </section>

      {/* Case Studies Grid */}
      <section className="py-16 lg:py-24" data-testid="case-studies-grid">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-8 max-w-6xl mx-auto">
            {caseStudies?.map((caseStudy, index) => {
              const slug = caseStudy.slug;

              return (
                <Card key={index} className="hover:shadow-soft transition-shadow group" data-testid={`case-study-card-${index}`}>
                  <CardHeader>
                    <div className="space-y-2">
                      <Badge variant="secondary" className="bg-gold/10 text-gold border-gold/20 w-fit">
                        {caseStudy.frontmatter.client}
                      </Badge>
                      <CardTitle className="text-xl text-charcoal dark:text-hwin-white group-hover:text-gold transition-colors">
                        {caseStudy.frontmatter.title}
                      </CardTitle>
                    </div>
                  </CardHeader>

                  <CardContent className="space-y-6">
                    {/* Tech Stack */}
                    <div className="space-y-2">
                      <h4 className="text-sm font-semibold text-charcoal dark:text-hwin-white">Technology Stack:</h4>
                      <div className="flex flex-wrap gap-1">
                        {caseStudy.frontmatter.stack.map((tech, techIndex) => (
                          <Badge key={techIndex} variant="outline" className="text-xs">
                            {tech}
                          </Badge>
                        ))}
                      </div>
                    </div>

                    {/* Key Results */}
                    <div className="space-y-2">
                      <h4 className="text-sm font-semibold text-charcoal dark:text-hwin-white">Key Results:</h4>
                      <ul className="space-y-1">
                        {caseStudy.frontmatter.results.slice(0, 3).map((result, resultIndex) => (
                          <li key={resultIndex} className="text-sm text-muted-foreground flex items-start space-x-2">
                            <span className="text-gold text-xs">●</span>
                            <span>{result}</span>
                          </li>
                        ))}
                      </ul>
                    </div>

                    <Button 
                      asChild 
                      variant="outline" 
                      className="w-full group-hover:bg-gold group-hover:text-charcoal transition-colors"
                      data-testid={`case-study-link-${index}`}
                    >
                      <Link href={`/hwin/work/${slug}`}>
                        Read Full Case Study
                        <ExternalLink className="ml-2 h-4 w-4" />
                      </Link>
                    </Button>
                  </CardContent>
                </Card>
              );
            }) || []}
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-16 lg:py-24 bg-muted/20" data-testid="case-studies-cta-section">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-3xl mx-auto text-center space-y-8">
            <h2 className="text-3xl lg:text-4xl font-bold text-charcoal dark:text-hwin-white">
              Ready to Be Our Next Success Story?
            </h2>
            <p className="text-lg text-muted-foreground">
              Let's discuss how we can achieve similar results for your business.
            </p>
            <Button 
              asChild 
              size="lg" 
              className="bg-gold hover:bg-gold/90 text-charcoal font-medium shadow-soft border-0"
              data-testid="case-studies-cta-button"
            >
              <Link href="/hwin/contact">
                Start Your Project
                <ArrowRight className="ml-2 h-4 w-4" />
              </Link>
            </Button>
          </div>
        </div>
      </section>
    </MarketingLayout>
  );
}

client/src/pages/marketing/case-study.ts.content:
import { useQuery } from "@tanstack/react-query";
import { useRoute } from "wouter";
import MarketingLayout from "@/components/layout/MarketingLayout";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Link } from "wouter";
import { loadCaseStudy } from "@/lib/contentLoader";
import { ArrowLeft, ArrowRight } from "lucide-react";
import ReactMarkdown from "react-markdown";
import { SeoHead } from "@/components/seo/SeoHead";
import { SITE_CONFIG } from "@/lib/constants";

export default function CaseStudyPage() {
  const [match, params] = useRoute("/hwin/work/:slug");
  const slug = params?.slug;

  const { data: caseStudyData, isLoading, error } = useQuery({
    queryKey: ["case-study", slug],
    queryFn: () => loadCaseStudy(slug!),
    enabled: !!slug,
  });

  if (isLoading) {
    return (
      <MarketingLayout>
        <div className="min-h-screen flex items-center justify-center">
          <div className="animate-pulse text-gold">Loading case study...</div>
        </div>
      </MarketingLayout>
    );
  }

  if (error || !caseStudyData) {
    return (
      <MarketingLayout>
        <div className="min-h-screen flex items-center justify-center">
          <div className="text-center space-y-4">
            <h1 className="text-2xl font-bold text-charcoal dark:text-hwin-white">
              Case Study Not Found
            </h1>
            <p className="text-muted-foreground">
              The case study you're looking for doesn't exist.
            </p>
            <Button asChild data-testid="back-to-case-studies">
              <Link href="/hwin/work">
                <ArrowLeft className="mr-2 h-4 w-4" />
                Back to Case Studies
              </Link>
            </Button>
          </div>
        </div>
      </MarketingLayout>
    );
  }

  const { frontmatter, content } = caseStudyData;

  return (
    <MarketingLayout>
      {/* Dynamic SEO */}
      <SeoHead 
        title={`${frontmatter.title} - ${frontmatter.client} Case Study | HwinNwin`}
        description={`Discover how HwinNwin helped ${frontmatter.client} achieve ${frontmatter.results[0] || 'significant business improvements'}. Case study with real results and implementation details.`}
        ogTitle={`${frontmatter.title} - ${frontmatter.client} Success Story`}
        ogDescription={`See how we helped ${frontmatter.client}: ${frontmatter.results.slice(0, 2).join(', ')}`}
        canonicalUrl={`${SITE_CONFIG.baseUrl}/hwin/work/${slug}`}
        keywords={[...(frontmatter.stack || []), frontmatter.client, 'case study', 'business results', 'implementation']}
      />
      {/* Back Navigation */}
      <div className="container mx-auto px-4 sm:px-6 lg:px-8 py-8">
        <Button asChild variant="ghost" data-testid="back-navigation">
          <Link href="/hwin/work">
            <ArrowLeft className="mr-2 h-4 w-4" />
            Back to Case Studies
          </Link>
        </Button>
      </div>

      {/* Hero Section */}
      <section className="py-12 lg:py-20" data-testid="case-study-hero">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto space-y-8">
            <div className="space-y-4">
              <Badge variant="secondary" className="bg-gold/10 text-gold border-gold/20" data-testid="client-name">
                {frontmatter.client}
              </Badge>

              <h1 className="text-4xl lg:text-5xl font-bold text-charcoal dark:text-hwin-white leading-tight" data-testid="case-study-title">
                {frontmatter.title}
              </h1>
            </div>

            {/* Technology Stack */}
            <div className="space-y-3" data-testid="technology-stack">
              <h3 className="text-lg font-semibold text-charcoal dark:text-hwin-white">
                Technology Stack
              </h3>
              <div className="flex flex-wrap gap-2">
                {frontmatter.stack.map((tech, index) => (
                  <Badge key={index} variant="outline" data-testid={`tech-${index}`}>
                    {tech}
                  </Badge>
                ))}
              </div>
            </div>

            {/* Key Results */}
            <div className="bg-muted/20 rounded-2xl p-8 space-y-4" data-testid="key-results">
              <h3 className="text-lg font-semibold text-charcoal dark:text-hwin-white">
                Key Results Achieved
              </h3>
              <ul className="space-y-3">
                {frontmatter.results.map((result, index) => (
                  <li key={index} className="flex items-start space-x-3" data-testid={`result-${index}`}>
                    <span className="text-gold font-bold">●</span>
                    <span className="text-muted-foreground">{result}</span>
                  </li>
                ))}
              </ul>
            </div>
          </div>
        </div>
      </section>

      {/* Main Content */}
      <section className="py-8 lg:py-16" data-testid="case-study-content">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto">
            <div className="prose prose-lg prose-gray dark:prose-invert max-w-none
                         prose-headings:text-charcoal dark:prose-headings:text-hwin-white
                         prose-p:text-muted-foreground prose-strong:text-charcoal dark:prose-strong:text-hwin-white
                         prose-blockquote:border-gold prose-blockquote:bg-gold/5 prose-blockquote:text-gold
                         prose-a:text-gold hover:prose-a:text-gold/80
                         prose-ul:text-muted-foreground prose-ol:text-muted-foreground" 
                         data-testid="case-study-text">
              <ReactMarkdown 
                components={{
                  blockquote: ({node, ...props}) => (
                    <blockquote className="border-l-4 border-gold bg-gold/5 pl-4 py-2 my-6 italic text-gold font-medium" {...props} />
                  ),
                  strong: ({node, ...props}) => (
                    <strong className="font-semibold text-charcoal dark:text-hwin-white" {...props} />
                  ),
                  h1: ({node, ...props}) => (
                    <h1 className="text-3xl font-bold text-charcoal dark:text-hwin-white mt-8 mb-4" {...props} />
                  ),
                  h2: ({node, ...props}) => (
                    <h2 className="text-2xl font-semibold text-charcoal dark:text-hwin-white mt-6 mb-3" {...props} />
                  ),
                  h3: ({node, ...props}) => (
                    <h3 className="text-xl font-medium text-charcoal dark:text-hwin-white mt-4 mb-2" {...props} />
                  ),
                  p: ({node, ...props}) => (
                    <p className="text-muted-foreground leading-relaxed mb-4" {...props} />
                  ),
                  ul: ({node, ...props}) => (
                    <ul className="list-disc list-inside text-muted-foreground space-y-2 mb-4" {...props} />
                  ),
                  ol: ({node, ...props}) => (
                    <ol className="list-decimal list-inside text-muted-foreground space-y-2 mb-4" {...props} />
                  ),
                  li: ({node, ...props}) => (
                    <li className="text-muted-foreground" {...props} />
                  )
                }}
              >
                {content}
              </ReactMarkdown>
            </div>
          </div>
        </div>
      </section>

      {/* CTA Section */}
      <section className="py-16 lg:py-24 bg-muted/20" data-testid="case-study-cta-section">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-3xl mx-auto text-center space-y-8">
            <h2 className="text-3xl lg:text-4xl font-bold text-charcoal dark:text-hwin-white">
              Inspired by This Success Story?
            </h2>
            <p className="text-lg text-muted-foreground">
              Let's discuss how we can achieve similar results for your business.
            </p>
            <div className="flex flex-col sm:flex-row gap-4 justify-center">
              <Button 
                asChild 
                size="lg" 
                className="bg-gold hover:bg-gold/90 text-charcoal font-medium shadow-soft border-0"
                data-testid="case-study-contact-cta"
              >
                <Link href="/hwin/contact">
                  Start Your Project
                  <ArrowRight className="ml-2 h-4 w-4" />
                </Link>
              </Button>

              <Button 
                asChild 
                variant="outline" 
                size="lg"
                data-testid="view-more-case-studies"
              >
                <Link href="/hwin/work">
                  View More Case Studies
                </Link>
              </Button>
            </div>
          </div>
        </div>
      </section>
    </MarketingLayout>
  );
}

client/src/pages/marketing/contact.tsx.content:
import { useQuery, useMutation } from "@tanstack/react-query";
import MarketingLayout from "@/components/layout/MarketingLayout";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from "@/components/ui/form";
import { useForm } from "react-hook-form";
import { zodResolver } from "@hookform/resolvers/zod";
import { contactFormSchema, type ContactForm } from "@shared/schema";
import { loadBrandData } from "@/lib/contentLoader";
import { apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { Mail, MapPin, ArrowRight, Calendar, ExternalLink, CheckCircle, Phone } from "lucide-react";
import { useState } from "react";

export default function ContactPage() {
  const { data: brandData, isLoading } = useQuery({
    queryKey: ["brand-data"],
    queryFn: loadBrandData,
  });

  const { toast } = useToast();
  const [isSubmitted, setIsSubmitted] = useState(false);

  const form = useForm<ContactForm>({
    resolver: zodResolver(contactFormSchema),
    defaultValues: {
      name: "",
      email: "",
      company: "",
      phone: "",
      service: "",
      message: "",
      website: "", // Honeypot field
      url: "", // Honeypot field
      honeypot: "" // Honeypot field
    },
  });

  const contactMutation = useMutation({
    mutationFn: (data: ContactForm) => apiRequest('/api/contact', 'POST', data),
    onSuccess: (response) => {
      setIsSubmitted(true);
      toast({
        title: "Message sent successfully!",
        description: "We'll be in touch within 24 hours.",
        duration: 5000,
      });
      form.reset();
    },
    onError: (error: any) => {
      toast({
        variant: "destructive",
        title: "Failed to send message",
        description: error.message || "Please try again later.",
      });
    },
  });

  const onSubmit = (data: ContactForm) => {
    contactMutation.mutate(data);
  };

  const handleBookCall = () => {
    const bookingLink = brandData?.organization?.booking_link;
    if (bookingLink && bookingLink !== "REPLACE_ME_CAL_COM_LINK") {
      window.open(bookingLink, '_blank', 'noopener,noreferrer');
    } else {
      toast({
        variant: "destructive",
        title: "Booking unavailable",
        description: "Please contact us directly to schedule a call.",
      });
    }
  };

  if (isLoading) {
    return (
      <MarketingLayout>
        <div className="min-h-screen flex items-center justify-center">
          <div className="animate-pulse text-gold">Loading...</div>
        </div>
      </MarketingLayout>
    );
  }

  return (
    <MarketingLayout>
      {/* Hero Section */}
      <section className="py-20 lg:py-32 bg-gradient-to-b from-background to-muted/20" data-testid="contact-hero">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="max-w-4xl mx-auto text-center space-y-8">
            <h1 className="text-4xl lg:text-6xl font-bold text-charcoal dark:text-hwin-white leading-tight" data-testid="contact-headline">
              Let's Work Together
            </h1>

            <p className="text-xl text-muted-foreground max-w-2xl mx-auto" data-testid="contact-subtitle">
              Ready to scale your business with structure, mindset, and excellence? Start the conversation.
            </p>

            {/* Cal.com Integration Button */}
            <div className="flex flex-col sm:flex-row gap-4 justify-center items-center mt-8">
              <Button 
                onClick={handleBookCall}
                size="lg" 
                className="bg-gold hover:bg-gold/90 text-charcoal font-semibold shadow-lg border-0 px-8 py-3"
                data-testid="book-strategy-call"
                aria-label="Book a strategy call with HwinNwin"
              >
                <Calendar className="mr-2 h-5 w-5" />
                Book a Strategy Call
                <ExternalLink className="ml-2 h-4 w-4" />
              </Button>

              <span className="text-sm text-muted-foreground">
                or send us a message below
              </span>
            </div>
          </div>
        </div>
      </section>

      {/* Contact Form & Info */}
      <section className="py-16 lg:py-24" data-testid="contact-section">
        <div className="container mx-auto px-4 sm:px-6 lg:px-8">
          <div className="grid lg:grid-cols-2 gap-12 max-w-6xl mx-auto">

            {/* Contact Form */}
            <Card className="shadow-soft" data-testid="contact-form-card">
              <CardHeader>
                <CardTitle className="text-2xl text-charcoal dark:text-hwin-white">
                  Send Us a Message
                </CardTitle>
              </CardHeader>
              <CardContent>
                {isSubmitted ? (
                  <div className="text-center space-y-4 py-8" data-testid="success-message">
                    <CheckCircle className="h-12 w-12 text-green-500 mx-auto" />
                    <h3 className="text-xl font-semibold text-charcoal dark:text-hwin-white">
                      Message Sent Successfully!
                    </h3>
                    <p className="text-muted-foreground">
                      Thank you for reaching out. We'll get back to you within 24 hours.
                    </p>
                    <Button 
                      onClick={() => setIsSubmitted(false)}
                      variant="outline"
                      data-testid="send-another-message"
                    >
                      Send Another Message
                    </Button>
                  </div>
                ) : (
                  <Form {...form}>
                    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6" data-testid="contact-form">
                      {/* Honeypot Fields - Hidden from users */}
                      <div style={{ display: 'none' }} aria-hidden="true">
                        <FormField
                          control={form.control}
                          name="website"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Website</FormLabel>
                              <FormControl>
                                <Input {...field} tabIndex={-1} autoComplete="off" />
                              </FormControl>
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="url"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>URL</FormLabel>
                              <FormControl>
                                <Input {...field} tabIndex={-1} autoComplete="off" />
                              </FormControl>
                            </FormItem>
                          )}
                        />
                        <FormField
                          control={form.control}
                          name="honeypot"
                          render={({ field }) => (
                            <FormItem>
                              <FormLabel>Honeypot</FormLabel>
                              <FormControl>
                                <Input {...field} tabIndex={-1} autoComplete="off" />
                              </FormControl>
                            </FormItem>
                          )}
                        />
                      </div>

                      {/* Name Field */}
                      <FormField
                        control={form.control}
                        name="name"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="name">Full Name *</FormLabel>
                            <FormControl>
                              <Input 
                                id="name"
                                placeholder="Your full name" 
                                {...field}
                                data-testid="input-name"
                                disabled={contactMutation.isPending}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Email Field */}
                      <FormField
                        control={form.control}
                        name="email"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="email">Email Address *</FormLabel>
                            <FormControl>
                              <Input 
                                id="email"
                                type="email" 
                                placeholder="your.email@company.com" 
                                {...field}
                                data-testid="input-email"
                                disabled={contactMutation.isPending}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Company Field */}
                      <FormField
                        control={form.control}
                        name="company"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="company">Company</FormLabel>
                            <FormControl>
                              <Input 
                                id="company"
                                placeholder="Your company name" 
                                {...field}
                                data-testid="input-company"
                                disabled={contactMutation.isPending}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Phone Field */}
                      <FormField
                        control={form.control}
                        name="phone"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="phone">Phone Number</FormLabel>
                            <FormControl>
                              <Input 
                                id="phone"
                                type="tel"
                                placeholder="+61 4XX XXX XXX" 
                                {...field}
                                data-testid="input-phone"
                                disabled={contactMutation.isPending}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Service Field */}
                      <FormField
                        control={form.control}
                        name="service"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="service">Service of Interest</FormLabel>
                            <Select 
                              onValueChange={field.onChange} 
                              value={field.value}
                              disabled={contactMutation.isPending}
                            >
                              <FormControl>
                                <SelectTrigger data-testid="select-service">
                                  <SelectValue placeholder="Select a service" />
                                </SelectTrigger>
                              </FormControl>
                              <SelectContent>
                                <SelectItem value="consulting">Business Consulting</SelectItem>
                                <SelectItem value="strategy">Strategic Planning</SelectItem>
                                <SelectItem value="implementation">Implementation Support</SelectItem>
                                <SelectItem value="custom">Custom Solution</SelectItem>
                                <SelectItem value="other">Other</SelectItem>
                              </SelectContent>
                            </Select>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Message Field */}
                      <FormField
                        control={form.control}
                        name="message"
                        render={({ field }) => (
                          <FormItem>
                            <FormLabel htmlFor="message">Message *</FormLabel>
                            <FormControl>
                              <Textarea 
                                id="message"
                                placeholder="Tell us about your business challenges and goals..."
                                rows={5}
                                {...field}
                                data-testid="textarea-message"
                                disabled={contactMutation.isPending}
                              />
                            </FormControl>
                            <FormMessage />
                          </FormItem>
                        )}
                      />

                      {/* Submit Button */}
                      <Button 
                        type="submit" 
                        size="lg" 
                        className="w-full bg-gold hover:bg-gold/90 text-charcoal font-medium shadow-soft border-0"
                        disabled={contactMutation.isPending}
                        data-testid="submit-contact-form"
                      >
                        {contactMutation.isPending ? (
                          <>
                            <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-charcoal mr-2"></div>
                            Sending...
                          </>
                        ) : (
                          <>
                            Send Message
                            <ArrowRight className="ml-2 h-4 w-4" />
                          </>
                        )}
                      </Button>
                    </form>
                  </Form>
                )}
              </CardContent>
            </Card>

            {/* Contact Information */}
            <div className="space-y-8" data-testid="contact-info">
              <div>
